<?php require_once 'config.php';require_login();$s=db()->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?');$s->execute([$_SESSION['user_id']]);$s=db()->prepare('SELECT n.*,g.hostel_name,g.app_name FROM notifications n LEFT JOIN app_groups g ON g.id=n.group_id WHERE n.user_id=? ORDER BY n.created_at DESC');$s->execute([$_SESSION['user_id']]);$items=$s->fetchAll();$pageTitle='Notifications';require 'header.php';?><h1>Notifications</h1><?php foreach($items as $n):?><div class="card"><h3><?=e($n['title'])?></h3><p><?=e($n['message'])?></p><small><?=e($n['created_at'])?></small><?php if($n['group_id']):?><p><a href="group.php?id=<?=(int)$n['group_id']?>">View Group-<?= (int)$n['group_id']?> →</a></p><?php endif;?></div><?php endforeach;if(!$items):?><div class="card">Abhi koi notification nahi hai.</div><?php endif;?><?php require 'footer.php';?>
